  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Extracorporeal membrane oxygenation (ECMO) for refractory cardiac arrest (RCA, ECPR) provides adequate systemic perfusion while the underlying cause may be diagnosed and treated. Whilst promising outcomes have been reported [1-3], survival rates vary widely [3] which is likely due to differences in study design, geographical",
      "reason": "The text describes the current state of knowledge (promising outcomes) and the uncertainty/variability in survival rates, attributing this to differences in study design."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Whilst promising outcomes have been reported [1-3], survival rates vary widely [3] which is likely due to differences in study design, geographical",
      "reason": "The need for the review is implied by the wide variation in survival rates and the need to understand the impact of study design and selection criteria, which is the focus of the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence provided that this is an update or replication of a previous systematic review, nor is there mention of similar existing reviews that necessitate an explanation of the need for this specific one."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review is not evaluating the intervention effect of ECPR itself (i.e., whether ECPR works), but rather the impact of selection criteria and study design on reported outcomes. Therefore, a mechanism of action for the intervention is not required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not focus on a complex intervention or delivery context requiring a logic model; it is a meta-analysis of observational studies regarding study design and selection criteria."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "We sought to analyse the survival rates in ECPR studies that had defined inclusion criteria for refractory out of hospital cardiac arrest (OHCA) and in hospital cardiac arrest (IHCA). Further, we sought to examine the association between the use of prospectively determined selection criteria (as opposed to retrospective no inclusion criteria) and the number of these inclusion criteria on reported survival outcomes.",
      "reason": "The authors explicitly state the objectives of the review in the Study Selection section, describing what they sought to analyze and examine."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Two reviewers using a pre-defined standardised data extraction form, extracted data as pertinent to the PICO.",
      "reason": "The review explicitly mentions the use of a PICO framework for data extraction, which implies the review's structure and comparisons are based on this framework."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We used the PICO (Population, Intervention, Comparison, Outcome) search format: Among adults with cardiac arrest in any setting (OHCA or IHCA) who qualify for ECPR by inclusion and exclusion parameters outlined (P), does receiving ECPR, including ECMO or cardiopulmonary bypass, during cardiac arrest (I), compared to manual CPR and/or mechanical CPR (C) without any mechanical circulatory support, change meaningful outcomes (favourable neurological status or survival at study end) (O). ... The population included adults (age above 12) with IHCA or OHCA of any origin. Animal studies, ecological studies, case reports, reviews, abstracts, editorials, comments, and letters to the editor were excluded. Studies with ≤ 5 patients receiving ECPR or studies that did not report the inclusion or exclusion criteria regarding the eligibility of ECPR or the timing of ECPR (i.e. during or after cardiac arrest) were excluded.",
      "reason": "The manuscript explicitly defines the PICO components, including population (adults with cardiac arrest), intervention (ECPR), comparison (manual/mechanical CPR), and outcomes. It also specifies eligible study designs (randomised trials, non-randomised controlled trials, observational studies) and exclusion criteria (animal studies, case reports, etc., and studies with small sample sizes or missing eligibility reporting)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Contemporary studies from January 2000 to June 2021 were included. Only English language studies were included.",
      "reason": "The manuscript specifies the dissemination time frame (January 2000 to June 2021) and language restriction (English only)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies specifically because outcomes were not measured versus not reported; therefore, this conditional requirement is not applicable."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Results are reported separately for pre-defined subgroups based on type of study (retrospective or prospective), and the location of cardiac arrest (IHCA vs OHCA).",
      "reason": "The manuscript specifies how studies were grouped for synthesis (subgroups based on study design and location of cardiac arrest)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There are no notable restrictions on study eligibility that require a specific rationale beyond standard systematic review inclusion/exclusion criteria."
    }
  ],
  "confidence": 100
}

